"use client";

import * as React from "react";
import { motion } from "motion/react";

export function ToggleSwitchTailwind({ label = "Reduce motion" }) {
  const [on, setOn] = React.useState(false);
  return (
    <button
      type="button"
      role="switch"
      aria-checked={on}
      onClick={() => setOn((v) => !v)}
      className="inline-flex items-center gap-3 rounded-lg text-sm text-zinc-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-[3px] focus-visible:outline-zinc-200"
    >
      <span className={"flex h-[26px] w-12 items-center rounded-full px-[3px] transition-colors " + (on ? "bg-sky-400" : "bg-zinc-800 ring-1 ring-inset ring-zinc-700")}>
        <motion.span
          animate={{ x: on ? 22 : 0 }}
          transition={{ type: "spring", stiffness: 700, damping: 32 }}
          className={"h-5 w-5 rounded-full shadow " + (on ? "bg-zinc-100" : "bg-zinc-400")}
        />
      </span>
      {label}
    </button>
  );
}
